CREATE TABLE media_items (
    id TEXT PRIMARY KEY,
    type TEXT,
    title TEXT,
    original_title TEXT,
    year INTEGER,
    tmdb_id INTEGER,
    tvdb_id INTEGER,
    imdb_id TEXT,
    metadata TEXT,
    monitored INTEGER NOT NULL DEFAULT 1,
    monitoring_preset TEXT NOT NULL DEFAULT 'all',
    category TEXT,
    category_override INTEGER NOT NULL DEFAULT 0,
    seasons_refreshed_at TEXT,
    quality_profile_id TEXT,
    inserted_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE episodes (
    id TEXT PRIMARY KEY,
    media_item_id TEXT NOT NULL,
    season_number INTEGER,
    episode_number INTEGER,
    title TEXT,
    air_date TEXT,
    metadata TEXT,
    monitored INTEGER NOT NULL DEFAULT 1,
    inserted_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE media_files (
    id TEXT PRIMARY KEY,
    media_item_id TEXT NOT NULL,
    episode_id TEXT,
    quality_profile_id TEXT,
    library_path_id TEXT,
    path TEXT,
    relative_path TEXT,
    size INTEGER,
    resolution TEXT,
    codec TEXT,
    hdr_format TEXT,
    audio_codec TEXT,
    bitrate INTEGER,
    verified_at TEXT,
    analyzed_at TEXT,
    analysis_attempts INTEGER NOT NULL DEFAULT 0,
    last_analysis_error TEXT,
    metadata TEXT,
    cover_blob TEXT,
    sprite_blob TEXT,
    vtt_blob TEXT,
    preview_blob TEXT,
    phash TEXT,
    generated_at TEXT,
    trashed_at TEXT,
    inserted_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE library_paths (
    id TEXT PRIMARY KEY,
    path TEXT,
    type TEXT,
    monitored INTEGER NOT NULL DEFAULT 1,
    scan_interval INTEGER NOT NULL DEFAULT 3600,
    last_scan_at TEXT,
    last_scan_status TEXT,
    last_scan_error TEXT,
    from_env INTEGER NOT NULL DEFAULT 0,
    disabled INTEGER NOT NULL DEFAULT 0,
    category_paths TEXT NOT NULL DEFAULT '{}',
    auto_organize INTEGER NOT NULL DEFAULT 0,
    auto_import INTEGER NOT NULL DEFAULT 0,
    write_nfo INTEGER NOT NULL DEFAULT 0,
    auto_rename INTEGER NOT NULL DEFAULT 1,
    quality_profile_id TEXT,
    updated_by_id TEXT,
    inserted_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
)
